module TopModule(
   input   clk,
   input   rst_n,
   output  reg [3:0] gray_out
);

reg [3:0] bin_out;
wire [3:0] gray_wire;
reg [3:0] bin_add_wire;
reg count_en;

// Toggle count enable every cycle
always @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      count_en <= 1'b0;
   end else begin
      count_en <= ~count_en;
   end
end

// Gray to binary conversion
always @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      bin_out <= 4'b0;
   end else if (count_en) begin
      bin_out <= {gray_wire[3], 
                 gray_wire[2] ^ gray_wire[3], 
                 gray_wire[1] ^ gray_wire[2] ^ gray_wire[3], 
                 gray_wire[0] ^ gray_wire[1] ^ gray_wire[2] ^ gray_wire[3]};
   end
end

// Binary increment
always @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      bin_add_wire <= 4'b0;
   end else if (count_en) begin
      bin_add_wire <= bin_out + 1'b1;
   end
end

// Binary to gray code conversion
assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

// Output register
always @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      gray_out <= 4'b0;
   end else if (count_en) begin
      gray_out <= gray_wire;
   end
end

endmodule
